<script setup lang="ts">
import { computed, reactive, watch } from 'vue'
import { useWorkspace } from '../composables/useWorkspace'
import StatusBadge from '../components/ui/StatusBadge.vue'
import type { ContentIdea } from '../types'
const { state, channels, channelLabels, reviewQueue, openIdea, generateBrief, submitReview, approve, handoff, saveIdeaChanges, closeIdea } = useWorkspace()
const form = reactive({ title:'',topic:'',targetAudience:'',tone:'',channels:[] as ContentIdea['channels'],media:'',scheduled:'' })
watch(()=>state.selected,(idea)=>{if(idea){form.title=idea.title;form.topic=idea.topic;form.targetAudience=idea.targetAudience;form.tone=idea.tone;form.channels=[...idea.channels];form.media='media://sample/'+idea.id;form.scheduled=new Date(Date.now()+86400000).toISOString().slice(0,16)}},{immediate:true})
const active = computed(()=>state.selected)
const activeId = computed(()=>active.value?.id ?? '')
const activeStatus = computed(()=>active.value?.status ?? 'draft')
const steps = ['Draft','Review','Approved','Handoff']
function completed(index:number){const s=active.value?.status;return index===0 ? !!s : index===1 ? ['review','approved','handed_off'].includes(s||'') : index===2 ? ['approved','handed_off'].includes(s||'') : s==='handed_off'}
async function save(){await saveIdeaChanges({title:form.title,topic:form.topic,targetAudience:form.targetAudience,tone:form.tone,channels:form.channels})}
function toggleChannel(channel: ContentIdea['channels'][number]){form.channels=form.channels.includes(channel)?form.channels.filter(c=>c!==channel):[...form.channels,channel]}
</script>
<template>
  <section class="page-section">
    <div class="page-intro-row"><div><span class="eyebrow">HUMAN-IN-THE-LOOP</span><h1>Quality has a <em>human touch.</em></h1><p>Review the exact brief version before it can be approved and handed off.</p></div><span class="review-total">{{reviewQueue.length}} in workflow</span></div>
    <div v-if="active" class="review-workspace">
      <div class="review-editor">
        <div class="panel-heading"><div><span class="eyebrow">CONTENT WORKFLOW</span><h3>{{active.title}}</h3></div><button class="icon-button" @click="closeIdea">×</button></div>
        <div class="workflow-progress"><div v-for="(step,index) in steps" :key="step" :class="{complete:completed(index)}"><span>{{completed(index)?'✓':index+1}}</span><small>{{step}}</small></div></div>
        <div class="editor-section"><div class="editor-heading"><span>01</span><div><strong>Content direction</strong><small>Edit before generating a new brief.</small></div></div><div class="form-grid"><label class="field"><span>Title</span><input v-model="form.title" :disabled="activeStatus==='handed_off'"/></label><label class="field"><span>Topic</span><input v-model="form.topic" :disabled="activeStatus==='handed_off'"/></label><label class="field"><span>Audience</span><input v-model="form.targetAudience" :disabled="activeStatus==='handed_off'"/></label><label class="field"><span>Tone</span><input v-model="form.tone" :disabled="activeStatus==='handed_off'"/></label></div><div class="field channel-editor"><span>Publishing channels</span><div class="channel-options"><button v-for="channel in channels" :key="channel" type="button" :disabled="activeStatus==='handed_off'" :class="{selected:form.channels.includes(channel)}" @click="toggleChannel(channel)">{{channelLabels[channel]}} <b>{{form.channels.includes(channel)?'✓':'+'}}</b></button></div></div><div class="form-actions"><button class="button button-secondary" :disabled="state.saving || activeStatus==='handed_off'" @click="save">Save changes & reset approval</button></div></div>
        <div class="editor-section"><div class="editor-heading"><span>02</span><div><strong>Creative brief</strong><small>Media reference and publishing schedule are required.</small></div></div><template v-if="!state.brief"><div class="form-grid"><label class="field"><span>Media reference</span><input v-model="form.media" :disabled="['approved','handed_off'].includes(activeStatus)"/></label><label class="field"><span>Scheduled at</span><input v-model="form.scheduled" type="datetime-local" :disabled="['approved','handed_off'].includes(activeStatus)"/></label></div><button v-if="!['approved','handed_off'].includes(activeStatus)" class="button button-primary" :disabled="state.saving || !form.media || !form.scheduled" @click="generateBrief(form.media,form.scheduled)">✦ Generate content brief</button></template><div v-else class="brief-content"><div class="brief-hook">{{state.brief.brief.hook}}</div><div class="brief-block"><span>MASTER COPY</span><p>{{state.brief.brief.masterCopy}}</p></div><div class="brief-block"><span>VISUAL DIRECTION</span><p>{{state.brief.brief.visual.overlay}} · {{state.brief.brief.visual.titleImage}}</p><small>{{state.brief.brief.visual.mediaReference}}</small></div><div class="brief-block"><span>PRODUCTION PLAN</span><p>{{state.brief.brief.productionPlan.format}}</p><ol><li v-for="step in state.brief.brief.productionPlan.steps" :key="step">{{step}}</li></ol></div><div class="brief-block"><span>CHANNEL VARIANTS</span><article v-for="(variant,channel) in state.brief.brief.channelVariants" :key="channel" class="variant-preview"><strong>{{channelLabels[channel as keyof typeof channelLabels] || channel}}</strong><p>{{variant.copy}}</p><small>{{variant.format}} · {{variant.cta}}</small></article></div><div class="brief-block"><span>EFFORT BREAKDOWN</span><div class="effort-row"><span>Research · {{state.brief.brief.effortMinutes.research}} min</span><span>Copy · {{state.brief.brief.effortMinutes.copyAndVariants}} min</span><span>Production · {{state.brief.brief.effortMinutes.production}} min</span><strong>Total · {{state.brief.brief.effortMinutes.total}} min</strong></div></div><p class="disclaimer">Synthetic demo content. Media and booking references are placeholders.</p></div></div>
        <div class="editor-section approval-section"><div class="editor-heading"><span>03</span><div><strong>Decision & handoff</strong><small>Only approved, assigned content can be handed off.</small></div></div><p v-if="!state.plan?.slots.some(s=>s.ideaId===activeId)" class="inline-warning">This idea is not assigned to a weekly plan yet. Add it to a plan before review.</p><button v-if="['draft','ready_for_planning'].includes(activeStatus)" class="button button-secondary full-width" :disabled="state.saving || !state.brief || !state.plan?.slots.some(s=>s.ideaId===activeId)" @click="submitReview">Submit for human review</button><button v-if="activeStatus==='review'" class="button button-primary full-width" :disabled="state.saving || !state.brief" @click="approve">Approve this exact version ✓</button><button v-if="activeStatus==='approved'" class="button button-primary full-width" :disabled="state.saving" @click="handoff">Create simulated handoff ↗</button><div v-if="activeStatus==='handed_off'" class="handoff-note"><strong>✓ Handoff completed</strong><p>Persisted in the backend. No social platform was contacted and nothing was published.</p></div><div v-if="state.handoff" class="handoff-payload"><span>HANDOFF ID</span><strong>{{state.handoff.handoffId}}</strong><small>Mode: simulated · Idempotent replay: {{state.handoff.idempotentReplay?'yes':'no'}}</small></div></div>
      </div>
      <aside class="review-rail"><div class="panel-heading"><div><span class="eyebrow">REVIEW QUEUE</span><h3>Choose content</h3></div><span class="queue-count">{{reviewQueue.length}}</span></div><button v-for="idea in reviewQueue" :key="idea.id" class="queue-item" :class="{active:activeId===idea.id}" @click="openIdea(idea)"><span><strong>{{idea.title}}</strong><small>{{idea.topic}}</small></span><StatusBadge :status="idea.status"/></button><p v-if="!reviewQueue.length" class="rail-empty">No content in review yet. Open a draft from the library to prepare its brief.</p><div class="human-note"><strong>Approval is version-bound</strong><p>Changing copy, channels, media or schedule invalidates the previous approval. A new review is required.</p></div></aside>
    </div>
    <div v-else class="review-grid"><button v-for="idea in reviewQueue" :key="idea.id" class="review-list-card" @click="openIdea(idea)"><div><span class="eyebrow">CONTENT ITEM</span><StatusBadge :status="idea.status"/></div><h3>{{idea.title}}</h3><p>{{idea.topic}}</p><span class="text-link">Open review →</span></button><div v-if="!reviewQueue.length" class="empty-state review-empty"><span>✓</span><h3>Nothing waiting for approval.</h3><p>Open a content idea, generate its brief and submit it for human review.</p><RouterLink to="/ideas" class="button button-primary">Go to content studio</RouterLink></div></div>
  </section>
</template>
